import React, { useEffect, useState } from "react";
import api from "../api";
import { io } from "socket.io-client";

type Ticket = {
  _id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  priority: string;
  createdBy: string;
  assignee: any;
  createdAt: string;
};

const socket = io("http://localhost:5050", {
  withCredentials: true,
});
